DO $$
DECLARE
  rec RECORD;
  cur_stage VARCHAR(20);
  cur_underwriter INT;
  cur_approved TIMESTAMP;
BEGIN
  FOR rec IN SELECT * FROM stage_events ORDER BY event_id LOOP
    SELECT stage, underwriter_id, approved_at INTO cur_stage, cur_underwriter, cur_approved
    FROM applications WHERE application_id = rec.application_id;

    IF rec.event_type = 1 AND cur_stage = 'draft' THEN
      UPDATE applications
      SET stage = 'under_review', underwriter_id = rec.assigned_underwriter_id
      WHERE application_id = rec.application_id;
    ELSIF rec.event_type = 2 AND cur_stage = 'under_review' AND rec.underwriter_id = cur_underwriter THEN
      UPDATE applications
      SET stage = 'awaiting_docs'
      WHERE application_id = rec.application_id;
    ELSIF rec.event_type = 3 AND cur_stage = 'awaiting_docs' THEN
      UPDATE applications
      SET stage = 'under_review'
      WHERE application_id = rec.application_id;
    ELSIF rec.event_type = 4 AND cur_stage = 'under_review' AND rec.underwriter_id = cur_underwriter THEN
      UPDATE applications
      SET stage = 'approved', approved_at = rec.event_timestamp
      WHERE application_id = rec.application_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM applications ORDER BY application_id;
